head.script:
scwin.onpageload = function() {
	console.log("페이지가 열렸습니다.");
    opt_result.setValue("scwin.onpageload 함수 실행<br>이벤트 실습을 시작하세요.");
};

scwin.ipt_name_onchange = function(info) {
    var name = ipt_name.getValue();
    opt_result.setValue(
        "이름이 변경되었습니다: " + name
    );
};

scwin.ipt_name_onblur = function(e) {
    var name = ipt_name.getValue();
     if (name === "") {
        opt_result.setValue("이름을 입력해주세요.");
    }
};

scwin.ipt_keyword_onkeyup = function(e) {
    var keyword = ipt_keyword.getValue();

    console.log("onkeyup - 현재 검색어:", keyword);

    opt_result.setValue(
        "현재 검색어: " + keyword
    );
};

scwin.sbx_dept_onchange = function(info) {
    var deptCode = sbx_dept.getValue();
    opt_result.setValue("선택한 부서 코드: "+ deptCode);
};



scwin.btn_search_onclick = function(e) {
    var name = ipt_name.getValue();
    var deptCode = sbx_dept.getValue();
    var keyword = ipt_keyword.getValue();

    opt_result.setValue(
        "이름: " + name
        + " / 부서코드: " + deptCode
        + " / 검색어: " + keyword
    );
};
